// Stop (return no items) on a non-trading day. Otherwise emit today's window + phase.
// phase: prep (early, e.g. 06:00), scan (OPEN-30m..OPEN-5m), freeze (>= OPEN-5m).
let cal = [];
for (const it of $input.all()) {
  const j = it.json;
  if (Array.isArray(j)) cal.push(...j);
  else if (j && j.date && (j.open || j.close)) cal.push(j);
  else if (j && Array.isArray(j.data)) cal.push(...j.data);
}
const todayET = new Date().toLocaleDateString('en-CA', { timeZone: 'America/New_York' });
const row = cal.find(c => c.date === todayET);
if (!row) return [];
const parts = new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', hour12: false, hour: '2-digit', minute: '2-digit' }).formatToParts(new Date());
const hh = Number(parts.find(p => p.type === 'hour').value) % 24;
const mm = Number(parts.find(p => p.type === 'minute').value);
const nowMin = hh * 60 + mm;
const [oh, om] = String(row.open).split(':').map(Number);
const openMin = oh * 60 + om;
let phase = 'prep';
if (nowMin >= openMin - 5) phase = 'freeze';
else if (nowMin >= openMin - 30) phase = 'scan';
return [{ json: { trade_date: todayET, open_time: row.open, close_time: row.close, early_close: String(row.close) !== '16:00', phase, now_et_min: nowMin } }];

// Union of movers gainers + most-actives (liquidity) into one candidate pool (benchmarks excluded).
const gate = $('Session gate').first().json;
const movers = $('Movers').first().json || {};
const ma = $('Most actives').first().json || {};
const gainers = movers.gainers || [];
const actives = ma.most_actives || [];
const BENCH = ['SPY', 'QQQ'];
const set = new Set();
for (const g of gainers) if (g.symbol) set.add(g.symbol);
for (const a of actives) if (a.symbol) set.add(a.symbol);
for (const b of BENCH) set.delete(b);
const pool = [...set].slice(0, 40);
return [{ json: { ...gate, pool, symbols_csv: pool.join(','), bench_csv: BENCH.join(','), gainers_n: gainers.length, actives_n: actives.length } }];

// Frozen v0 ranking: liquidity-gated gap rank. Gates: price>=$5, dollar_vol>=FLOOR.
// Rank survivors by abs(gap%) desc, cap 10, append SPY/QQQ benchmarks. Deterministic.
const base = $('Build candidate pool').first().json;
const snaps = $('Snapshots').first().json || {};
const movers = $('Movers').first().json || {};
const gm = {}; for (const g of (movers.gainers || [])) gm[g.symbol] = g;
const PRICE_FLOOR = 5, DVOL_FLOOR = 5000000, CAP = 10;
const rows = [];
for (const sym of base.pool) {
  const s = snaps[sym] || {};
  const db = s.dailyBar || {}, pdb = s.prevDailyBar || {}, lq = s.latestQuote || {}, lt = s.latestTrade || {};
  const price = (db.c != null ? db.c : (lt.p != null ? lt.p : (gm[sym] ? gm[sym].price : null)));
  const vol = (db.v != null ? db.v : null);
  const prevC = (pdb.c != null ? pdb.c : null);
  let gap = (gm[sym] && gm[sym].percent_change != null) ? gm[sym].percent_change
            : ((price != null && prevC) ? ((price - prevC) / prevC * 100) : null);
  const dvol = (price != null && vol != null) ? price * vol : null;
  let spread_bps = null;
  if (lq.ap && lq.bp && (lq.ap + lq.bp) > 0) spread_bps = Math.round(10000 * (lq.ap - lq.bp) / ((lq.ap + lq.bp) / 2) * 1000) / 1000;
  const pass = price != null && price >= PRICE_FLOOR && dvol != null && dvol >= DVOL_FLOOR && gap != null;
  rows.push({ symbol: sym, gap_pct: gap, price, dollar_vol: dvol, spread_bps, in_movers: !!gm[sym], pass });
}
const ranked = rows.filter(r => r.pass).sort((a, b) => Math.abs(b.gap_pct) - Math.abs(a.gap_pct)).slice(0, CAP)
  .map((r, i) => ({ symbol: r.symbol, role: 'candidate', rank: i + 1, gap_pct: r.gap_pct, price: r.price, dollar_vol: r.dollar_vol, spread_bps: r.spread_bps }));
const bench = (base.bench_csv || '').split(',').filter(Boolean).map(s => ({ symbol: s, role: 'benchmark' }));
const symbols = [...ranked, ...bench];
const cfg = { ranking: 'liq_gap_v0', price_floor: PRICE_FLOOR, dollar_vol_floor: DVOL_FLOOR, cap: CAP, benchmarks: bench.map(b => b.symbol) };
return [{ json: {
  trade_date: base.trade_date, open_time: base.open_time, close_time: base.close_time, early_close: base.early_close, phase: base.phase,
  symbols_json: JSON.stringify(symbols), candidate_count: ranked.length,
  scan_payload: JSON.stringify({ scanned: rows.length, ranked, gainers_n: base.gainers_n, actives_n: base.actives_n, at: new Date().toISOString() }),
  discovery_cov: JSON.stringify({ pool: base.pool.length, gainers_n: base.gainers_n, actives_n: base.actives_n, passed: ranked.length }),
  ranking_version: 'liq_gap_v0', config_hash: 'liq_gap_v0:' + JSON.stringify(cfg),
  freshness: JSON.stringify({ quote_age_ms: 2000, bar_arrival_ms: 5000, heartbeat_stale_ms: 15000, dashboard_ms: 90000 })
} }];

